"""Autonomous executor — executes raw shell commands generated by the LLM with streaming output."""

from __future__ import annotations

import asyncio
import logging
import os
import sys
import time as _time
from dataclasses import dataclass, field
from typing import Any

from .events import Event, EventType
from .exceptions import PermissionDeniedError, ToolExecutionError, ToolNotFoundError
from .executor import BaseExecutor
from .models import ExecutionPlan, PlanStatus, PlanStep, StepStatus

logger = logging.getLogger(__name__)


@dataclass
class CommandResult:
    label: str
    lines: list[str] = field(default_factory=list)
    exit_code: int | None = None
    done: bool = False
    output: str = ""
    error: str = ""


class AutonomousExecutor(BaseExecutor):
    """Executes raw shell commands from the LLM with live streaming output.

    Falls back to ToolRegistry for non-command steps and attempts to parse
    shell output through the parser registry when the tool name is known.
    """

    def __init__(
        self,
        max_workers: int = 10,
        permission_gate: Any = None,
        command_review: bool = True,
        registry: Any = None,
    ) -> None:
        super().__init__(max_workers=max_workers, permission_gate=permission_gate)
        self._command_review = command_review
        self._custom_handlers: dict[str, Any] = {}
        self._registry = registry

    @property
    def command_review(self) -> bool:
        return self._command_review

    @command_review.setter
    def command_review(self, value: bool) -> None:
        self._command_review = value

    async def execute_plan(
        self,
        plan: ExecutionPlan,
        executor_fn: Any = None,
        live_display: bool = True,
    ) -> ExecutionPlan:
        """Execute plan steps as shell commands with dependency-aware scheduling.

        Parameters
        ----------
        plan:
            The execution plan with command-based steps.
        executor_fn:
            Optional custom step executor override (unused; reserved for API parity).
        live_display:
            Whether to show live streaming output (default: True).
        """
        del executor_fn  # API parity with BaseExecutor / RegistryExecutor
        self._budget.reset_timer()
        plan.status = PlanStatus.ACTIVE

        await self._event_bus.emit(
            Event(
                type=EventType.PLAN_CREATED,
                source="executor_autonomous",
                data={"plan_id": plan.id, "goal": plan.goal, "steps": len(plan.steps)},
            )
        )

        # Pre-review all shell commands (kept independent of the permission gate)
        if self._command_review:
            approved = await self._review_commands(plan)
            if not approved:
                plan.status = PlanStatus.CANCELLED
                return plan

        # Pre-gather sudo passwords before any live display starts,
        # so the user is prompted while the terminal is free.
        self._prefetch_sudo_passwords(plan)

        cmd_states = self._build_cmd_states(plan)
        state_by_id = {s.id: st for s, st in zip(plan.steps, cmd_states)}

        if live_display and cmd_states:
            plan = await self._execute_with_live_display(plan, state_by_id)
        else:
            plan = await self._execute_dependency_aware(plan, state_by_id)

        plan.status = PlanStatus.COMPLETED if not plan.has_failures else PlanStatus.FAILED
        await self._event_bus.emit(
            Event(
                type=EventType.PLAN_COMPLETE,
                source="executor_autonomous",
                data={
                    "plan_id": plan.id,
                    "status": plan.status.value,
                    "progress": plan.progress_pct,
                },
            )
        )
        return plan

    async def _review_commands(self, plan: ExecutionPlan) -> bool:
        """Review all shell commands via the confirmation gate."""
        from .shell_review import review_and_confirm, review_refusal_message

        for s in plan.steps:
            if not s.command:
                continue
            reason = "Raw shell command from LLM-generated plan"
            reviewed = review_and_confirm(s.command, "raw", reason)
            if reviewed is None:
                logger.warning(
                    "Command review refused (%s): %s",
                    review_refusal_message(reason),
                    s.command[:60],
                )
                return False
            s.command = reviewed
        return True

    def _build_cmd_states(self, plan: ExecutionPlan) -> list[CommandResult]:
        states = []
        for s in plan.steps:
            if s.command:
                states.append(CommandResult(label=f"$ {s.command}"))
            elif s.tool and s.tool not in ("execute_plan", "_", ""):
                states.append(CommandResult(label=s.tool))
            else:
                states.append(CommandResult(label="(no command)"))
        return states

    def _mark_skipped(
        self,
        step: PlanStep,
        state: CommandResult | None,
        reason: str,
    ) -> None:
        """Mark *step* SKIPPED without starting any handler/subprocess."""
        step.status = StepStatus.SKIPPED
        step.result = {"status": "skipped", "error": reason}
        if state is not None:
            state.done = True
            state.exit_code = -1
            state.error = reason
            state.lines.append(reason)

    def _skip_blocked_dependents(
        self,
        plan: ExecutionPlan,
        state_by_id: dict[str, CommandResult],
    ) -> bool:
        """Skip pending steps whose dependencies failed/skipped/missing.

        Returns True if at least one step was skipped.
        """
        skipped_any = False
        for step in list(plan.pending_steps):
            for dep_id in step.dependencies:
                dep = plan.get_step(dep_id)
                if dep is None or dep.status in (StepStatus.FAILED, StepStatus.SKIPPED):
                    reason = (
                        f"Skipped: dependency '{dep_id}' did not succeed"
                        if dep is not None
                        else f"Skipped: missing dependency '{dep_id}'"
                    )
                    self._mark_skipped(step, state_by_id.get(step.id), reason)
                    skipped_any = True
                    break
        return skipped_any

    def _resolve_deadlock(
        self,
        plan: ExecutionPlan,
        state_by_id: dict[str, CommandResult],
    ) -> None:
        """Fail-closed: skip remaining pending steps (cycles / unreachable deps)."""
        for step in list(plan.pending_steps):
            self._mark_skipped(
                step,
                state_by_id.get(step.id),
                "Skipped: unresolvable dependency cycle or deadlock",
            )

    async def _execute_dependency_aware(
        self,
        plan: ExecutionPlan,
        state_by_id: dict[str, CommandResult],
    ) -> ExecutionPlan:
        """Run only steps whose dependencies succeeded; bound via worker pool."""
        while not plan.is_complete:
            if self._budget.is_exhausted:
                break

            ready_steps = plan.get_ready_steps()
            if not ready_steps:
                if self._skip_blocked_dependents(plan, state_by_id):
                    continue
                if plan.pending_steps:
                    logger.warning(
                        "Plan %s deadlocked or cyclic; skipping remaining pending steps",
                        plan.id,
                    )
                    self._resolve_deadlock(plan, state_by_id)
                break

            # Bound concurrency via the inherited AsyncWorkerPool.
            tasks = [
                self._pool.submit(self._exec_one, step, state_by_id[step.id])
                for step in ready_steps
            ]
            results = await asyncio.gather(*tasks, return_exceptions=True)
            for i, res in enumerate(results):
                if isinstance(res, BaseException):
                    step = ready_steps[i]
                    logger.error("Step %s exception: %s", step.id, res, exc_info=res)
                    step.status = StepStatus.FAILED
                    step.result = {"status": "error", "error": str(res)}
                    state = state_by_id.get(step.id)
                    if state is not None:
                        state.done = True
                        state.exit_code = -1
                        state.error = str(res)

            # After failures, eagerly skip dependents so they never start.
            self._skip_blocked_dependents(plan, state_by_id)

        return plan

    async def _exec_one(
        self, step: PlanStep, state: CommandResult
    ) -> tuple[PlanStep, dict[str, Any]]:
        """Execute a single plan step and capture output.

        The permission gate / authorizer runs **before** any handler or
        subprocess is started. A denying gate yields zero spawns.
        """
        if not self._budget.consume_iteration():
            step.status = StepStatus.FAILED
            step.result = {"status": "error", "error": "Budget exhausted"}
            state.done = True
            state.exit_code = -1
            state.error = "Budget exhausted"
            return step, step.result

        # ── SX-003: authorize before any RUNNING / spawn ──────────────
        try:
            await self._check_permissions(step)
        except PermissionDeniedError as exc:
            step.status = StepStatus.FAILED
            step.result = {"status": "error", "error": str(exc), "denied": True}
            state.exit_code = -1
            state.error = str(exc)
            state.done = True
            state.lines.append(str(exc))
            self._tracker.record(step.tool or "shell", step.command or str(step.args), False)
            await self._event_bus.emit(
                Event(
                    type=EventType.PLAN_STEP_FAILED,
                    source="executor_autonomous",
                    data={"step_id": step.id, "error": str(exc), "denied": True},
                )
            )
            if self._on_step_progress:
                res = self._on_step_progress(step)
                if hasattr(res, "__await__"):
                    _ = await res  # type: ignore[misc]
            return step, step.result

        step.status = StepStatus.RUNNING
        await self._event_bus.emit(
            Event(
                type=EventType.PLAN_STEP_START,
                source="executor_autonomous",
                data={"step_id": step.id, "tool": step.tool or "shell"},
            )
        )

        if self._on_step_progress:
            res = self._on_step_progress(step)
            if hasattr(res, "__await__"):
                _ = await res  # type: ignore[misc]

        self.normalise_step(step)

        try:
            from siyarix.stealth import stealth_engine

            stealth_enabled = bool(stealth_engine.config.enabled)
        except (ImportError, AttributeError):
            stealth_enabled = False
        if stealth_enabled:
            try:
                delay = stealth_engine.get_randomized_delay(1.0)
                if delay > 0:
                    await asyncio.sleep(delay)
            except Exception:
                pass

        start = _time.monotonic()
        try:
            if not step.command:
                # No shell command — likely a tool name with args
                result = await self._execute_tool_step(step)
                state.exit_code = 0 if result.get("status") == "success" else 1
                out = (result.get("output") or "").strip()
                err = (result.get("error") or "").strip()
                if out:
                    state.lines.extend(out.split("\n"))
                    state.output = out
                if err:
                    state.lines.extend(err.split("\n"))
                    state.error = err
            else:
                result = await self._execute_shell_command(step, state)
                # Parse shell command output through the tool's parser when available
                result = self._try_parse_output(step, result)

            step.duration_ms = (_time.monotonic() - start) * 1000
            step.result = result

            success = result.get("status") == "success"
            step.status = StepStatus.COMPLETED if success else StepStatus.FAILED
            self._tracker.record(step.tool or "shell", step.command or str(step.args), success)
            state.done = True

            if success:
                await self._event_bus.emit(
                    Event(
                        type=EventType.PLAN_STEP_COMPLETE,
                        source="executor_autonomous",
                        data={"step_id": step.id, "duration_ms": step.duration_ms},
                    )
                )
            else:
                await self._event_bus.emit(
                    Event(
                        type=EventType.PLAN_STEP_FAILED,
                        source="executor_autonomous",
                        data={"step_id": step.id, "error": result.get("error", "")},
                    )
                )

        except Exception as e:
            step.duration_ms = (_time.monotonic() - start) * 1000
            step.status = StepStatus.FAILED
            step.result = {"status": "error", "error": str(e)}
            state.exit_code = -1
            state.done = True
            self._tracker.record(step.tool or "shell", step.command or str(step.args), False)

        if self._on_step_progress:
            res = self._on_step_progress(step)
            if hasattr(res, "__await__"):
                _ = await res  # type: ignore[misc]

        return step, step.result

    async def _execute_tool_step(self, step: PlanStep) -> dict[str, Any]:
        """Execute a step that has a tool name but no shell command."""
        handler = self._custom_handlers.get(step.tool)
        if handler:
            return await handler(step)
        if self._registry:
            try:
                result = await self._registry.execute(step.tool, **step.args)
                return self._try_parse_output(step, result)
            except (ToolNotFoundError, ToolExecutionError) as e:
                return {"status": "error", "error": str(e), "tool": step.tool}
        # Fallback: try generic command execution as last resort
        if step.tool:
            try:
                from .subprocess_utils import safe_run_async

                fallback_cmd = [step.tool]
                if step.args.get("target"):
                    fallback_cmd.append(step.args["target"])
                result = await safe_run_async(fallback_cmd, timeout=30)
                if result.exit_code != 127 and result.exit_code != 126:
                    return {
                        "status": "success",
                        "output": result.stdout,
                        "error": result.stderr,
                        "tool": step.tool,
                    }
            except Exception:
                pass
        return {
            "status": "error",
            "error": f"Tool '{step.tool}' not available. Try using a raw shell command via the 'command' field instead, or install the tool. Available alternatives depend on what's on your system PATH.",
        }

    async def _execute_shell_command(self, step: PlanStep, state: CommandResult) -> dict[str, Any]:
        """Execute a shell command with subprocess.

        If the command fails because a tool is not installed and we are in a
        TTY, the user is prompted to auto‑install the missing tool and the
        command is retried once.
        """
        from .subprocess_utils import get_platform_shell_cmd, safe_run_async_stream

        cmd_timeout = int(step.timeout or 300)
        shell_cmd = get_platform_shell_cmd(step.command or "")

        exec_result = await safe_run_async_stream(
            shell_cmd,
            timeout=cmd_timeout,
            on_stdout=lambda line: state.lines.append(line),
            on_stderr=lambda line: state.lines.append(line),
        )

        # ── Auto‑install prompt when a tool is missing ──────────────
        if exec_result.exit_code in (126, 127) and sys.stdout and sys.stdout.isatty():
            tool_name = self._extract_tool_from_command(step.command or "")
            if tool_name:
                from .tool_installer import ToolInstaller, tty_confirm
                from .tool_models import invalidate_which_cache

                want = tty_confirm(
                    f"\n[yellow]Tool [cyan]{tool_name}[/cyan] is required but not installed."
                    f"\nDo you want to install it now?[/yellow]",
                    default=True,
                )
                if want:
                    installer = ToolInstaller()
                    if installer.install_tool(tool_name):
                        invalidate_which_cache()
                        state.lines.append(f"✓ {tool_name} installed — retrying command")
                        # Retry once
                        exec_result = await safe_run_async_stream(
                            shell_cmd,
                            timeout=cmd_timeout,
                            on_stdout=lambda line: state.lines.append(line),
                            on_stderr=lambda line: state.lines.append(line),
                        )

        state.exit_code = exec_result.exit_code
        state.output = exec_result.stdout
        state.error = exec_result.stderr
        state.done = True

        return {
            "status": "success" if not exec_result.exit_code else "error",
            "output": exec_result.stdout,
            "error": exec_result.stderr,
            "exit_code": exec_result.exit_code,
        }

    @staticmethod
    def _extract_tool_from_command(command: str) -> str | None:
        """Extract the primary tool name from a shell command string."""
        import shlex as _shlex

        try:
            parts = _shlex.split(command)
        except Exception:
            parts = command.strip().split()
        if not parts:
            return None
        idx = 0
        if parts[idx] in ("sh", "bash") and len(parts) > idx + 1 and parts[idx + 1] == "-c":
            inner = _shlex.split(parts[idx + 2]) if len(parts) > idx + 2 else []
            parts = inner
            idx = 0
        if not parts:
            return None
        if parts[idx] in ("sudo", "doas"):
            idx += 1
            if idx < len(parts) and parts[idx] == "-S":
                idx += 1
        return parts[idx] if idx < len(parts) else None

    def _prefetch_sudo_passwords(self, plan: ExecutionPlan) -> None:
        """Pre-cache sudo passwords for any plan steps that need them.

        Calling this *before* the Live display starts avoids the conflict
        between ``rich.prompt.Prompt`` and ``rich.live.Live``, each of which
        wants exclusive control of the terminal.
        """
        import re as _re

        from siyarix.subprocess_utils import _get_sudo_password as _gsp

        needs_sudo = False
        for step in plan.steps:
            if step.command and _re.search(r"\bsudo\b", step.command):
                needs_sudo = True
                break

        if needs_sudo:
            _gsp()  # caches the password in the module-level global

    async def _execute_with_live_display(
        self,
        plan: ExecutionPlan,
        state_by_id: dict[str, CommandResult],
    ) -> ExecutionPlan:
        """Execute with rich live display while dependency-aware scheduling runs."""
        cmd_states = [state_by_id[s.id] for s in plan.steps]
        exec_task = asyncio.ensure_future(self._execute_dependency_aware(plan, state_by_id))

        from rich.live import Live
        from rich.panel import Panel as RichPanel

        _old_term = os.environ.get("TERM")
        os.environ["TERM"] = "xterm-256color"

        if cmd_states:
            focus_idx = 0
            wave_start = _time.time()

            with Live(refresh_per_second=10, screen=False) as live:
                while True:
                    await asyncio.sleep(0.1)
                    if exec_task.done():
                        break
                    if cmd_states[focus_idx].done:
                        unfinished = [i for i, st in enumerate(cmd_states) if not st.done]
                        if unfinished:
                            focus_idx = unfinished[0]
                        else:
                            break

                    st = cmd_states[focus_idx]
                    elapsed = _time.time() - wave_start
                    icon = "·" if st.exit_code is None else ("✓" if not st.exit_code else "✗")
                    border = (
                        "cyan" if st.exit_code is None else ("green" if not st.exit_code else "red")
                    )

                    panel_content = (
                        "\n".join(st.lines[-200:])
                        if st.lines
                        else (
                            f"Running... ({elapsed:.1f}s)"
                            if st.exit_code is None
                            else "(no output)"
                        )
                    )

                    live.update(
                        RichPanel(
                            panel_content,
                            title=f"{icon} {st.label}",
                            subtitle=f"Elapsed: {elapsed:.1f}s" if st.exit_code is None else None,
                            border_style=border,
                        )
                    )

        await exec_task

        if _old_term is not None:
            os.environ["TERM"] = _old_term
        else:
            os.environ.pop("TERM", None)

        return plan

    async def _execute_batch(
        self,
        plan: ExecutionPlan,
        exec_tasks: list[Any],
        cmd_states: list[CommandResult],
    ) -> ExecutionPlan:
        """Legacy batch helper retained for tests; prefer dependency-aware path."""
        del cmd_states
        raw_results = await asyncio.gather(*exec_tasks, return_exceptions=True)
        for i, result in enumerate(raw_results):
            if isinstance(result, BaseException):
                logger.error("Step execution exception: %s", result, exc_info=result)
                continue
            step, step_result = result
            for s in plan.steps:
                if s.id == step.id:
                    s.status = step.status
                    s.result = step_result
                    s.duration_ms = step.duration_ms
                    break
        return plan

    def register_handler(self, name: str, handler: Any) -> None:
        """Register a custom handler for non-command tool steps."""
        self._custom_handlers[name] = handler

    # ── Step normalisation ─────────────────────────────────────────────────

    def normalise_step(self, step: PlanStep) -> None:
        """Validate and normalise a plan step before execution.

        - Extracts tool name from command when tool is empty
        - Populates args from command content when args are empty
        - Marks step origin in metadata
        """
        if not step.tool and step.command:
            first_word = step.command.strip().split()[0] if step.command.strip() else ""
            if first_word:
                step.tool = first_word

        if step.tool and not step.args and step.command:
            parts = step.command.strip().split()
            if len(parts) > 1:
                non_flag_args = [p for p in parts[1:] if not p.startswith("-")]
                if non_flag_args:
                    step.args["target"] = non_flag_args[-1]
                flag_parts = [p for p in parts[1:] if p.startswith("-")]
                if flag_parts:
                    step.args["flags"] = " ".join(flag_parts)

        step.metadata.setdefault("origin", "autonomous")

    def _try_parse_output(self, step: PlanStep, result: dict[str, Any]) -> dict[str, Any]:
        """Run the parser registry on shell-command output when the tool is known."""
        if not step.tool or not self._registry:
            return result
        parser_registry = getattr(self._registry, "_parser_registry", None)
        if not parser_registry or not hasattr(parser_registry, "has_parser"):
            return result
        if not parser_registry.has_parser(step.tool):
            return result
        output = (result.get("output") or "").strip()
        if not output:
            return result
        try:
            parsed = parser_registry.parse(step.tool, output)
            if parsed:
                result["findings"] = parsed
        except Exception:
            logger.debug("Parser failed for tool %s (output length=%d)", step.tool, len(output))
        return result


__all__ = [
    "AutonomousExecutor",
    "CommandResult",
]
